<template><div class="page"><div class="head"><div><h2>故障事件重演</h2><p>已接入项目生成的磨损、润滑和综合退化数据，支持时间窗口、倍速、播放和暂停。</p></div><el-button :loading="loading" @click="loadEvents">刷新事件</el-button></div><div class="stats"><el-card shadow="never"><small>可重演事件</small><strong>{{events.length}}</strong></el-card><el-card shadow="never"><small>当前数据源</small><strong class="source">{{selected?.diagnosis?.source_csv||selected?.name||'—'}}</strong></el-card><el-card shadow="never"><small>样本点</small><strong>{{selected?.diagnosis?.sample_count||curve.count||'—'}}</strong></el-card></div><el-card shadow="never"><el-alert v-if="!loading&&!events.length" title="尚未发现可重演事件，请确认数据库迁移已执行且仿真数据目录存在。" type="warning" show-icon :closable="false"/><el-form inline><el-form-item label="故障事件"><el-select v-model="eventId" filterable placeholder="选择仿真故障事件" @change="selectEvent"><el-option v-for="e in events" :key="e.id" :value="e.id" :label="`${e.name} / ${formatTime(e.start_time)}—${formatTime(e.end_time??e.start_time)}`"/></el-select></el-form-item><el-form-item label="开始"><el-input-number v-model="form.start" :min="selected?.start_time??0" :max="form.end" :precision="2"/></el-form-item><el-form-item label="结束"><el-input-number v-model="form.end" :min="form.start" :max="selected?.end_time??form.end" :precision="2"/></el-form-item><el-form-item label="倍速"><el-select v-model="form.speed"><el-option v-for="n in [.5,1,2,5,10]" :key="n" :value="n" :label="`${n}x`"/></el-select></el-form-item><el-button type="primary" :loading="creating" :disabled="!eventId" @click="create">创建重演</el-button></el-form></el-card><el-card v-if="replay" shadow="never" class="result"><div class="toolbar"><el-tag :type="replay.state==='finished'?'success':'primary'">{{states[replay.state]}}</el-tag><b>当前时间 {{formatTime(replay.current_time)}}</b><span>窗口 {{formatTime(replay.window_start)}}—{{formatTime(replay.window_end)}}</span><span>{{replay.speed}}x</span><el-progress class="progress" :percentage="progress" :show-text="false"/><el-button @click="control('restart')">重置</el-button><el-button type="primary" @click="control(replay.state==='playing'?'pause':'play')">{{replay.state==='playing'?'暂停':'播放'}}</el-button></div><ReportChart :option="chart"/><el-table :data="curve.rows.slice(-30).reverse()" stripe><el-table-column v-for="k in curve.columns" :key="k" :prop="k" :label="labels[k]||k"/></el-table></el-card></div></template>
<script setup>import{ref,computed,onMounted,onUnmounted}from'vue';import{ElMessage}from'element-plus';import ReportChart from'../components/ReportChart.vue';const events=ref([]),eventId=ref(null),replay=ref(null),curve=ref({columns:[],rows:[],series:{},count:0}),form=ref({start:0,end:10,speed:1}),loading=ref(false),creating=ref(false),states={paused:'已暂停',playing:'播放中',finished:'已结束'},labels={time:'时间',current:'电流',voltage:'电压'};let timer;const selected=computed(()=>events.value.find(x=>x.id===eventId.value));const progress=computed(()=>{if(!replay.value)return 0;const span=replay.value.window_end-replay.value.window_start;return span<=0?100:Math.min(100,Math.round((replay.value.current_time-replay.value.window_start)/span*100))});const formatTime=v=>Number(v??0).toFixed(2);async function api(url,options={}){const r=await fetch(url,{credentials:'include',headers:{'Content-Type':'application/json',...(options.headers||{})},...options});const j=await r.json();if(!r.ok)throw Error(j.error||j.detail||`请求失败 ${r.status}`);return j}async function loadEvents(){loading.value=true;try{events.value=(await api('/api/v1/phm/fault-events/')).results||[];if(events.value.length&&!eventId.value){eventId.value=events.value[0].id;selectEvent()}}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}function selectEvent(){const e=selected.value;if(e){form.value={start:e.start_time,end:e.end_time??e.start_time,speed:1};replay.value=null;curve.value={columns:[],rows:[],series:{},count:0}}}async function create(){creating.value=true;try{const j=await api(`/api/v1/phm/fault-events/${eventId.value}/replays/`,{method:'POST',body:JSON.stringify(form.value)});replay.value=j.replay;curve.value=j.curve;startTimer();ElMessage.success('重演数据已加载')}catch(e){ElMessage.error(e.message)}finally{creating.value=false}}async function control(action){try{const j=await api(`/api/v1/phm/fault-replays/${replay.value.id}/`,{method:'POST',body:JSON.stringify({action,elapsed:.5})});replay.value=j.replay;curve.value=j.curve;startTimer()}catch(e){ElMessage.error(e.message)}}function startTimer(){clearInterval(timer);timer=setInterval(async()=>{if(replay.value?.state==='playing')await control('tick')},500)}const chart=computed(()=>({tooltip:{trigger:'axis'},legend:{},xAxis:{type:'value',name:'时间'},yAxis:{type:'value',scale:true},series:Object.entries(curve.value.series||{}).map(([name,data])=>({name:labels[name]||name,type:'line',showSymbol:false,smooth:true,data}))}));onMounted(loadEvents);onUnmounted(()=>clearInterval(timer))</script>
<style scoped>.page{max-width:1400px}.head{display:flex;justify-content:space-between;margin-bottom:18px}.head h2{margin:0 0 8px}.head p{color:#718198;margin:0}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:16px}.stats small{display:block;color:#718198}.stats strong{display:block;font-size:26px;margin-top:6px}.stats .source{font-size:16px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.el-select{width:280px}.result{margin-top:18px}.toolbar{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.progress{width:180px}@media(max-width:800px){.stats{grid-template-columns:1fr}.head{display:block}.head .el-button{margin-top:12px}}</style>
